cgb_tree() { local cgb_node=$1; shift; case "$cgb_node" in root) cgb_tree left "$@"; cgb_tree right "$@";; left) cgb_tree marked "$@"; cgb_tree empty "$@";; marked) "$@";; right|empty) return 0;; esac; }
cgb_tree root git stash push --include-untracked --no-pager --no-ext-diff --no-textconv
)

